def gen(rng):
    def fmt(a, qs):
        return f"{len(a)} {len(qs)}\n" + ' '.join(map(str, a)) + '\n' + '\n'.join(f'{l} {r}' for l, r in qs)

    def rq(n, q):
        out = []
        for _ in range(q):
            l = rng.randrange(n)
            r = rng.randrange(l, n)
            out.append((l, r))
        return out

    tests = [fmt([5], [(0, 0)]), fmt([1, 2, 3, 4], [(0, 3), (1, 2), (3, 3)]), fmt([-1, -1, -1], [(0, 2), (1, 1)]), fmt([10**9, -10**9], [(0, 1), (1, 1), (0, 0)])]
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            a = [rng.randint(-20, 20) for _ in range(n)]
            tests.append(fmt(a, rq(n, rng.randint(1, 10))))
    n = 100000
    big = lambda: [rng.randint(-10**9, 10**9) for _ in range(n)]
    tests.append(fmt(big(), rq(n, 100000)))
    tests.append(fmt(list(range(n)), [(0, n - 1)] * 50000 + [(i % 50, n - 1 - i % 50) for i in range(50000)]))
    tests.append(fmt(sorted(big(), reverse=True), [(rng.randrange(0, 100), rng.randrange(n - 100, n)) for _ in range(100000)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(2000)], rq(2000, 100000)))
    return tests

